console.log("数据变更tree");
const ai_kb_graph_relation = data[0].id;
const graph_tree = view.getCtrl("TREE", "treeexpbar2_tree");
const graph = graph_tree.graph;

// 移除其他节点状态
graph.setElementState(
    graph.getNodeData().reduce((acc, node) => {
        acc[node.id] = [];
        return acc;
    }, {})
);
// 移除其他连线状态
graph.setElementState(
    graph.getEdgeData().reduce((acc, edge) => {
        acc[edge.id] = [];
        return acc;
    }, {})
)
//高亮当前连线
graph_tree.highlightElement(ai_kb_graph_relation, "edge");
//聚焦连线
await graph.focusElement(ai_kb_graph_relation);
graph.zoomTo(1.2);

console.log("数据变更tree");
