getPSDETreeNodeDataItems.scriptCode:
var type = data.type ? data.type : "";
var codeValue = type;
var codeItem = "";

if (type && type !== "") {
    console.log("实体类型绘制图标");
    var codelisttag = "ai__entity_types";
    const app = await ibiz.hub.getApp(context.srfappid);
    const codelist = app.codeList;
    codeItem = await codelist.getItem(codelisttag, type, context, "");
    if(codeItem && codeItem.text){
       codeValue = codeItem.text;
    }
    if (codeItem && codeItem.icon) {
        // icon 是字符串，需要先解析为 JSON 对象
        let iconArray;
        try {
            iconArray = JSON.parse(codeItem.icon);
        } catch (e) {
            console.error("解析 icon 字符串失败:", e);
            return codeValue; // 解析失败时回退到文本
        }

        if (Array.isArray(iconArray) && iconArray.length > 0) {
            const icon = iconArray[0];
            // 构建文件下载URL
            const fileUrl = ibiz.util.file.calcFileUpDownUrl(
                context,
                {},
                {},
                { osscat: icon.folder }
            );
            // 替换文件ID
            const downloadUrl = fileUrl.downloadUrl.replace("%fileId%", icon.id);
            if (icon.name && icon.name.split(".").pop() === "svg") {
                try {
                    const response = await fetch(downloadUrl);
                    if (!response.ok) {
                        return "";
                    }
                    const blob = await response.blob();

                    // 6将SVG转换为base64
                    const base64Data = await new Promise((resolve, reject) => {
                        const reader = new FileReader();
                        reader.onloadend = () => {
                            let data = reader.result;
                            if (data) {
                                // 转换MIME类型
                                data = data.replace("data:application/octet-stream;base64", "data:image/svg+xml;base64");
                            }
                            resolve(data);
                        };
                        reader.onerror = reject;
                        reader.readAsDataURL(blob);
                    });
                    const imgstr = `<img alt="${codeValue}" src="${base64Data}" style="width: 25px; height: 25px;">`;
                    return `<div class="ibiz-code-list__item" style="height: 36px; line-height: 36px; display: flex; align-items: center; gap: 5px;">  ${imgstr} ${codeValue}</div>`;
                } catch (error) {
                    ibiz.log.error(error);
                }
            }else{
                const imgstr = `<img alt="${codeValue}" src="${downloadUrl}" style="width: 25px; height: 25px;">`;
                return `<div class="ibiz-code-list__item" style="height: 36px; line-height: 36px; display: flex; align-items: center; gap: 5px;">  ${imgstr} ${codeValue}</div>`;
            }
        }
    }
}
return codeValue;

